        ('UA-1', 'R-238', '{record,record_validity}'::text[], '"REVIEWED"'::jsonb, '"record_validity":"INVALID"', '"record_validity":"REVIEWED"'),
        ('UA-2', 'R-238', '{fields,action_phrase,source}'::text[], '"W-UPDATED"'::jsonb, '("action_phrase":[{]"value":' || '(?:null|' || '"(?:[^"' || chr(92) || chr(92) || ']|' || chr(92) || chr(92) || '.)*"' || ')' || ',"validity":"[A-Z_]+","start_pos":(?:null|[0-9]+),"source":)' || '(?:null|' || '"(?:[^"' || chr(92) || chr(92) || ']|' || chr(92) || chr(92) || '.)*"' || ')', chr(92) || '1"W-UPDATED"'),
        ('UA-3', 'R-5000', '{record,record_validity}'::text[], '"REVIEWED"'::jsonb, '"record_validity":"(VALID|INVALID|BROKEN)"', '"record_validity":"REVIEWED"')
    )
        SELECT c.id, c.name, c.expected, c.actual
        FROM (VALUES
            ('P-01', 'Step 6B access_log_json rows', '5000', (SELECT count(*)::text FROM log_regex_json.access_log_json)),
            ('P-02', 'Step 6B access_log_jsonb rows', '5000', (SELECT count(*)::text FROM log_regex_json.access_log_jsonb)),
            ('P-03', 'canonical fingerprint recorded in both Step 6B table comments', 'aeaef32371fa8143c088d4fdce9f6e0d/aeaef32371fa8143c088d4fdce9f6e0d', (SELECT substring(obj_description('log_regex_json.access_log_json'::regclass, 'pg_class') FROM 'md5 ([0-9a-f]{32})') || '/' || substring(obj_description('log_regex_json.access_log_jsonb'::regclass, 'pg_class') FROM 'md5 ([0-9a-f]{32})'))),
            ('P-04', 'indexes of schema log_regex_json = the 14 indexes of the Step 6D end state', 'access_log_json_i1a_record_validity,access_log_json_i1b_entity_type_code,access_log_json_i1c_status_code,access_log_json_i1d_latitude_degrees,access_log_json_i1e_event_timestamp_utc,access_log_json_pkey,access_log_jsonb_i1a_record_validity,access_log_jsonb_i1b_entity_type_code,access_log_jsonb_i1c_status_code,access_log_jsonb_i1d_latitude_degrees,access_log_jsonb_i1e_event_timestamp_utc,access_log_jsonb_i2_gin_jsonb_ops,access_log_jsonb_i3_gin_jsonb_path_ops,access_log_jsonb_pkey', (SELECT string_agg(ic.relname::text, ',' ORDER BY ic.relname::text COLLATE "C") FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid JOIN pg_class c ON c.oid = i.indrelid WHERE c.relnamespace = 'log_regex_json'::regnamespace)),
            ('P-05', 'Step 6D indexes valid, ready and live', '14', (SELECT count(*)::text FROM pg_index i JOIN pg_class c ON c.oid = i.indrelid WHERE c.relnamespace = 'log_regex_json'::regnamespace AND i.indisvalid AND i.indisready AND i.indislive)),
            ('P-06', 'Step 6B tables rows inserted / updated / deleted (json, jsonb), as sql/38 G-07', '5000/0/0 5000/0/0', (SELECT string_agg(s.n_tup_ins || '/' || (s.n_tup_upd + s.n_tup_hot_upd) || '/' || s.n_tup_del, ' ' ORDER BY s.relname) FROM pg_stat_user_tables s WHERE s.schemaname = 'log_regex_json')),
            ('P-07', 'other PostgreSQL client sessions connected (all databases)', '4', (SELECT count(*)::text FROM pg_stat_activity WHERE backend_type = 'client backend' AND pid <> pg_backend_pid())),
            ('P-08', 'other client sessions not idle (active, idle in transaction, fastpath, disabled)', '0', (SELECT count(*)::text FROM pg_stat_activity WHERE backend_type = 'client backend' AND pid <> pg_backend_pid() AND state IS DISTINCT FROM 'idle')),
            ('S-01', 'canonical_doc rows / distinct log_id', '5000/5000', (SELECT count(*) || '/' || count(DISTINCT log_id) FROM log_regex_json_write.canonical_doc)),
            ('S-02', 'md5 of staged texts (log_id order, LF) = Step 6B canonical fingerprint', 'aeaef32371fa8143c088d4fdce9f6e0d', (SELECT md5(string_agg(doc_text, chr(10) ORDER BY log_id)) FROM log_regex_json_write.canonical_doc)),
            ('S-03', 'staged bytes / characters = Step 6B canonical input', '8416033/8415454', (SELECT sum(octet_length(doc_text)) || '/' || sum(char_length(doc_text)) FROM log_regex_json_write.canonical_doc)),
            ('S-04', 'staged texts byte-identical to the stored Step 6B json text (same log_id)', '5000', (SELECT count(*)::text FROM log_regex_json_write.canonical_doc c JOIN log_regex_json.access_log_json j ON j.log_id = c.log_id WHERE j.doc::text = c.doc_text)),
            ('S-05', 'staged texts cast to jsonb = the Step 6B jsonb documents (same log_id)', '5000', (SELECT count(*)::text FROM log_regex_json_write.canonical_doc c JOIN log_regex_json.access_log_jsonb b ON b.log_id = c.log_id WHERE b.doc = c.doc_text::jsonb)),
            ('S-06', 'staged texts that are JSON objects with unique keys', '5000', (SELECT count(*)::text FROM log_regex_json_write.canonical_doc WHERE doc_text IS JSON OBJECT WITH UNIQUE KEYS)),
            ('E-01', 'designed update variants: row set, path, new value', 'UA-1:R-238:record.record_validity="REVIEWED" UA-2:R-238:fields.action_phrase.source="W-UPDATED" UA-3:R-5000:record.record_validity="REVIEWED"', (SELECT string_agg(variant || ':' || row_set || ':' || array_to_string(path, '.') || '=' || new_value::text, ' ' ORDER BY variant) FROM design_variant)),
            ('E-02', 'staged documents with record_validity INVALID (row set R-238)', '238', (SELECT count(*)::text FROM log_regex_json_write.canonical_doc c WHERE c.doc_text::jsonb #>> '{record,record_validity}' = 'INVALID')),
            ('E-03', 'expected_update rows per variant', 'UA-1:238 UA-2:238 UA-3:5000', (SELECT string_agg(variant || ':' || n, ' ' ORDER BY variant) FROM (SELECT variant, count(*) AS n FROM log_regex_json_write.expected_update GROUP BY variant) s)),
            ('E-04', 'expected_update (variant, log_id) = designed row sets exactly (differences)', '0', (SELECT count(*)::text FROM (SELECT variant, log_id FROM log_regex_json_write.expected_update) e FULL JOIN (SELECT v.variant, c.log_id FROM design_variant v JOIN log_regex_json_write.canonical_doc c ON v.row_set = 'R-5000' OR (v.row_set = 'R-238' AND c.doc_text::jsonb #>> '{record,record_validity}' = 'INVALID')) d ON d.variant = e.variant AND d.log_id = e.log_id WHERE e.log_id IS NULL OR d.log_id IS NULL)),
            ('E-05', 'source documents with exactly one pattern match, per variant', 'UA-1:238 UA-2:238 UA-3:5000', (SELECT string_agg(variant || ':' || n, ' ' ORDER BY variant) FROM (SELECT e.variant, count(*) AS n FROM log_regex_json_write.expected_update e JOIN design_variant v ON v.variant = e.variant JOIN log_regex_json_write.canonical_doc c ON c.log_id = e.log_id WHERE regexp_count(c.doc_text, v.pattern) = 1 GROUP BY e.variant) s)),
            ('E-06', 'expected text = jsonb_set of the staged document (independent derivation), per variant', 'UA-1:238 UA-2:238 UA-3:5000', (SELECT string_agg(variant || ':' || n, ' ' ORDER BY variant) FROM (SELECT e.variant, count(*) AS n FROM log_regex_json_write.expected_update e JOIN design_variant v ON v.variant = e.variant JOIN log_regex_json_write.canonical_doc c ON c.log_id = e.log_id WHERE e.new_text::jsonb = jsonb_set(c.doc_text::jsonb, v.path, v.new_value) GROUP BY e.variant) s)),
            ('E-07', 'expected text = the substitution, a unique-key JSON object, different from the source, per variant', 'UA-1:238 UA-2:238 UA-3:5000', (SELECT string_agg(variant || ':' || n, ' ' ORDER BY variant) FROM (SELECT e.variant, count(*) AS n FROM log_regex_json_write.expected_update e JOIN design_variant v ON v.variant = e.variant JOIN log_regex_json_write.canonical_doc c ON c.log_id = e.log_id WHERE e.new_text = regexp_replace(c.doc_text, v.pattern, v.replacement) AND e.new_text IS JSON OBJECT WITH UNIQUE KEYS AND e.new_text <> c.doc_text GROUP BY e.variant) s)),
            ('O-01', 'relations in log_regex_json_write = the four designed tables and their primary keys only', 'i:access_log_json_w_pkey i:access_log_jsonb_w_pkey i:canonical_doc_pkey i:expected_update_pkey r:access_log_json_w r:access_log_jsonb_w r:canonical_doc r:expected_update', (SELECT string_agg(c.relkind::text || ':' || c.relname, ' ' ORDER BY c.relkind, c.relname::text COLLATE "C") FROM pg_class c WHERE c.relnamespace = 'log_regex_json_write'::regnamespace)),
            ('O-02', 'other objects in log_regex_json_write (functions, sequences, views, triggers, policies, rules, non-PK constraints, types)', '0', ((SELECT count(*) FROM pg_proc WHERE pronamespace = 'log_regex_json_write'::regnamespace) + (SELECT count(*) FROM pg_class WHERE relnamespace = 'log_regex_json_write'::regnamespace AND relkind NOT IN ('r', 'i')) + (SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid WHERE c.relnamespace = 'log_regex_json_write'::regnamespace) + (SELECT count(*) FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid WHERE c.relnamespace = 'log_regex_json_write'::regnamespace) + (SELECT count(*) FROM pg_rewrite r JOIN pg_class c ON c.oid = r.ev_class WHERE c.relnamespace = 'log_regex_json_write'::regnamespace) + (SELECT count(*) FROM pg_constraint k WHERE k.connamespace = 'log_regex_json_write'::regnamespace AND k.contype <> 'p') + (SELECT count(*) FROM pg_type ty WHERE ty.typnamespace = 'log_regex_json_write'::regnamespace AND ty.typrelid = 0 AND ty.typelem = 0))::text),
            ('O-03', 'dependencies between log_regex_json_write and log_regex / log_regex_json relations', '0', (SELECT count(*)::text FROM pg_depend d JOIN pg_class c1 ON d.classid = 'pg_class'::regclass AND c1.oid = d.objid JOIN pg_class c2 ON d.refclassid = 'pg_class'::regclass AND c2.oid = d.refobjid WHERE (c1.relnamespace = 'log_regex_json_write'::regnamespace AND c2.relnamespace IN ('log_regex'::regnamespace, 'log_regex_json'::regnamespace)) OR (c2.relnamespace = 'log_regex_json_write'::regnamespace AND c1.relnamespace IN ('log_regex'::regnamespace, 'log_regex_json'::regnamespace)))),
            ('O-04', 'write tables empty before measurement (json_w / jsonb_w)', '0/0', (SELECT (SELECT count(*) FROM log_regex_json_write.access_log_json_w) || '/' || (SELECT count(*) FROM log_regex_json_write.access_log_jsonb_w))),
            ('O-05', 'access_log_json_w = Step 6B access_log_json definition (persistence, reloptions, columns, storage, compression, constraints)', 'same', (SELECT CASE WHEN (SELECT c.relpersistence::text || ' ' || coalesce(array_to_string(c.reloptions, ','), '') FROM pg_class c WHERE c.oid = 'log_regex_json.access_log_json'::regclass) || ' | ' || (SELECT string_agg(a.attnum || ':' || a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull || ':' || a.attstorage::text || ':' || coalesce(nullif(a.attcompression::text, ''), '-'), ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = 'log_regex_json.access_log_json'::regclass AND a.attnum > 0 AND NOT a.attisdropped) || ' | ' || (SELECT string_agg(k.contype::text || ' ' || regexp_replace(regexp_replace(pg_get_constraintdef(k.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g'), ',' ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid = 'log_regex_json.access_log_json'::regclass) = (SELECT c.relpersistence::text || ' ' || coalesce(array_to_string(c.reloptions, ','), '') FROM pg_class c WHERE c.oid = 'log_regex_json_write.access_log_json_w'::regclass) || ' | ' || (SELECT string_agg(a.attnum || ':' || a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull || ':' || a.attstorage::text || ':' || coalesce(nullif(a.attcompression::text, ''), '-'), ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = 'log_regex_json_write.access_log_json_w'::regclass AND a.attnum > 0 AND NOT a.attisdropped) || ' | ' || (SELECT string_agg(k.contype::text || ' ' || regexp_replace(regexp_replace(pg_get_constraintdef(k.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g'), ',' ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid = 'log_regex_json_write.access_log_json_w'::regclass) THEN 'same' ELSE 'different' END)),
            ('O-06', 'access_log_jsonb_w = Step 6B access_log_jsonb definition (persistence, reloptions, columns, storage, compression, constraints)', 'same', (SELECT CASE WHEN (SELECT c.relpersistence::text || ' ' || coalesce(array_to_string(c.reloptions, ','), '') FROM pg_class c WHERE c.oid = 'log_regex_json.access_log_jsonb'::regclass) || ' | ' || (SELECT string_agg(a.attnum || ':' || a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull || ':' || a.attstorage::text || ':' || coalesce(nullif(a.attcompression::text, ''), '-'), ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = 'log_regex_json.access_log_jsonb'::regclass AND a.attnum > 0 AND NOT a.attisdropped) || ' | ' || (SELECT string_agg(k.contype::text || ' ' || regexp_replace(regexp_replace(pg_get_constraintdef(k.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g'), ',' ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid = 'log_regex_json.access_log_jsonb'::regclass) = (SELECT c.relpersistence::text || ' ' || coalesce(array_to_string(c.reloptions, ','), '') FROM pg_class c WHERE c.oid = 'log_regex_json_write.access_log_jsonb_w'::regclass) || ' | ' || (SELECT string_agg(a.attnum || ':' || a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull || ':' || a.attstorage::text || ':' || coalesce(nullif(a.attcompression::text, ''), '-'), ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = 'log_regex_json_write.access_log_jsonb_w'::regclass AND a.attnum > 0 AND NOT a.attisdropped) || ' | ' || (SELECT string_agg(k.contype::text || ' ' || regexp_replace(regexp_replace(pg_get_constraintdef(k.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g'), ',' ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid = 'log_regex_json_write.access_log_jsonb_w'::regclass) THEN 'same' ELSE 'different' END)),
            ('O-07', 'write-schema tables with autovacuum disabled', '4', (SELECT count(*)::text FROM pg_class WHERE relnamespace = 'log_regex_json_write'::regnamespace AND relkind = 'r' AND reloptions @> ARRAY['autovacuum_enabled=false'])),
            ('D-01', 'designed indexes per configuration and type (X-0: none; X-2 ... X-4: jsonb only)', 'X-1/json:5 X-1/jsonb:5 X-2/jsonb:6 X-3/jsonb:6 X-4/jsonb:7', (SELECT string_agg(config_id || '/' || doc_type || ':' || n, ' ' ORDER BY config_id, doc_type) FROM (SELECT config_id, doc_type, count(*) AS n FROM design_index GROUP BY 1, 2) s)),
            ('D-02', 'designed statements not in the designed form (name, _w table of the same type, method, GIN only on jsonb, no cast)', '0', (SELECT count(*)::text FROM design_index x WHERE NOT starts_with(x.ddl, 'CREATE INDEX ' || x.index_name || ' ON log_regex_json_write.access_log_' || x.doc_type || '_w ') OR NOT starts_with(x.index_name, 'access_log_' || x.doc_type || '_w_') OR NOT starts_with(x.source_index, 'access_log_' || x.doc_type || '_') OR x.index_name <> replace(x.source_index, 'access_log_' || x.doc_type || '_', 'access_log_' || x.doc_type || '_w_') OR x.method NOT IN ('btree', 'gin') OR (x.method = 'gin') <> (strpos(x.ddl, ' USING gin (doc ' || x.opclass || ')') > 0) OR (x.method = 'gin' AND x.doc_type <> 'jsonb') OR strpos(x.ddl, '::json') > 0)),
            ('D-03', 'designed method and operator class = those of the live Step 6D source index', '29', (SELECT count(*)::text FROM design_index x JOIN pg_class si ON si.oid = to_regclass('log_regex_json.' || x.source_index) JOIN pg_index i ON i.indexrelid = si.oid JOIN pg_am am ON am.oid = si.relam JOIN pg_opclass opc ON opc.oid = i.indclass[0] WHERE am.amname = x.method AND opc.opcname = x.opclass AND i.indnatts = 1)),
            ('D-04', 'X-1 json and jsonb statements identical apart from table and index names (5 concepts)', '5', (SELECT count(*)::text FROM design_index a JOIN design_index b ON b.config_id = a.config_id AND b.concept = a.concept WHERE a.config_id = 'X-1' AND a.doc_type = 'json' AND b.doc_type = 'jsonb' AND a.method = b.method AND a.opclass = b.opclass AND replace(a.ddl, 'access_log_json_w', 'T') = replace(b.ddl, 'access_log_jsonb_w', 'T'))),
            ('D-05', 'X-2 / X-3 / X-4 btree statements = the X-1 jsonb statements', '15', (SELECT count(*)::text FROM design_index a JOIN design_index x ON x.config_id = 'X-1' AND x.doc_type = 'jsonb' AND x.index_name = a.index_name AND x.ddl = a.ddl WHERE a.config_id IN ('X-2', 'X-3', 'X-4') AND a.method = 'btree')),
            ('D-06', 'X-1 json = the live secondary indexes of access_log_json; X-4 = those of access_log_jsonb (current Step 6D set)', 'same/same', (SELECT CASE WHEN (SELECT string_agg(source_index, ',' ORDER BY source_index COLLATE "C") FROM design_index WHERE config_id = 'X-1' AND doc_type = 'json') = (SELECT string_agg(ic.relname::text, ',' ORDER BY ic.relname::text COLLATE "C") FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid WHERE i.indrelid = 'log_regex_json.access_log_json'::regclass AND NOT i.indisprimary) THEN 'same' ELSE 'different' END || '/' || CASE WHEN (SELECT string_agg(source_index, ',' ORDER BY source_index COLLATE "C") FROM design_index WHERE config_id = 'X-4' AND doc_type = 'jsonb') = (SELECT string_agg(ic.relname::text, ',' ORDER BY ic.relname::text COLLATE "C") FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid WHERE i.indrelid = 'log_regex_json.access_log_jsonb'::regclass AND NOT i.indisprimary) THEN 'same' ELSE 'different' END)),
            ('D-07', 'GIN operator classes per configuration', 'X-2:jsonb_ops X-3:jsonb_path_ops X-4:jsonb_ops,jsonb_path_ops', (SELECT string_agg(config_id || ':' || ops, ' ' ORDER BY config_id) FROM (SELECT config_id, string_agg(opclass, ',' ORDER BY opclass) AS ops FROM design_index WHERE method = 'gin' GROUP BY config_id) s))
        ) AS c (id, name, expected, actual)
    LOOP
        IF chk.expected IS NOT DISTINCT FROM chk.actual THEN
            RAISE NOTICE '% PASS  %: %', chk.id, chk.name, chk.actual;
        ELSE
            v_failed := v_failed + 1;
            RAISE WARNING '% FAIL  %: expected %, actual %', chk.id, chk.name, chk.expected, chk.actual;
        END IF;
    END LOOP;
    PERFORM set_config('step6e.preflight_failures', v_failed::text, true);
END
$static$;

DO $indexes$
DECLARE
    v_failed   integer := current_setting('step6e.preflight_failures')::integer;
    v_config   text;
    v_expected text;
    v_actual   text;
    v_count    bigint;
    ixd        record;
BEGIN
    -- I-X0: primary keys only, equal to the Step 6B primary keys
    WITH design_index (config_id, doc_type, concept, index_name, method, opclass, ddl, source_index) AS (VALUES
        ('X-1', 'json', 'I-1a', 'access_log_json_w_i1a_record_validity', 'btree', 'text_ops', 'CREATE INDEX access_log_json_w_i1a_record_validity ON log_regex_json_write.access_log_json_w ((doc->''record''->>''record_validity''))', 'access_log_json_i1a_record_validity'),
        ('X-1', 'json', 'I-1b', 'access_log_json_w_i1b_entity_type_code', 'btree', 'text_ops', 'CREATE INDEX access_log_json_w_i1b_entity_type_code ON log_regex_json_write.access_log_json_w ((doc->''fields''->''entity_type''->>''code''))', 'access_log_json_i1b_entity_type_code'),
        ('X-1', 'json', 'I-1c', 'access_log_json_w_i1c_status_code', 'btree', 'int4_ops', 'CREATE INDEX access_log_json_w_i1c_status_code ON log_regex_json_write.access_log_json_w (((doc->''fields''->''status''->>''code'')::integer))', 'access_log_json_i1c_status_code'),
        ('X-1', 'json', 'I-1d', 'access_log_json_w_i1d_latitude_degrees', 'btree', 'numeric_ops', 'CREATE INDEX access_log_json_w_i1d_latitude_degrees ON log_regex_json_write.access_log_json_w (((doc->''fields''->''latitude''->>''degrees'')::numeric))', 'access_log_json_i1d_latitude_degrees'),
        ('X-1', 'json', 'I-1e', 'access_log_json_w_i1e_event_timestamp_utc', 'btree', 'text_ops', 'CREATE INDEX access_log_json_w_i1e_event_timestamp_utc ON log_regex_json_write.access_log_json_w ((doc->''fields''->''event_timestamp''->>''utc''))', 'access_log_json_i1e_event_timestamp_utc'),
        ('X-1', 'jsonb', 'I-1a', 'access_log_jsonb_w_i1a_record_validity', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1a_record_validity ON log_regex_json_write.access_log_jsonb_w ((doc->''record''->>''record_validity''))', 'access_log_jsonb_i1a_record_validity'),
        ('X-1', 'jsonb', 'I-1b', 'access_log_jsonb_w_i1b_entity_type_code', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1b_entity_type_code ON log_regex_json_write.access_log_jsonb_w ((doc->''fields''->''entity_type''->>''code''))', 'access_log_jsonb_i1b_entity_type_code'),
        ('X-1', 'jsonb', 'I-1c', 'access_log_jsonb_w_i1c_status_code', 'btree', 'int4_ops', 'CREATE INDEX access_log_jsonb_w_i1c_status_code ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''status''->>''code'')::integer))', 'access_log_jsonb_i1c_status_code'),
        ('X-1', 'jsonb', 'I-1d', 'access_log_jsonb_w_i1d_latitude_degrees', 'btree', 'numeric_ops', 'CREATE INDEX access_log_jsonb_w_i1d_latitude_degrees ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''latitude''->>''degrees'')::numeric))', 'access_log_jsonb_i1d_latitude_degrees'),
        ('X-1', 'jsonb', 'I-1e', 'access_log_jsonb_w_i1e_event_timestamp_utc', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1e_event_timestamp_utc ON log_regex_json_write.access_log_jsonb_w ((doc->''fields''->''event_timestamp''->>''utc''))', 'access_log_jsonb_i1e_event_timestamp_utc'),
        ('X-2', 'jsonb', 'I-1a', 'access_log_jsonb_w_i1a_record_validity', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1a_record_validity ON log_regex_json_write.access_log_jsonb_w ((doc->''record''->>''record_validity''))', 'access_log_jsonb_i1a_record_validity'),
