        ('X-2', 'jsonb', 'I-1c', 'access_log_jsonb_w_i1c_status_code', 'btree', 'int4_ops', 'CREATE INDEX access_log_jsonb_w_i1c_status_code ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''status''->>''code'')::integer))', 'access_log_jsonb_i1c_status_code'),
        ('X-2', 'jsonb', 'I-1d', 'access_log_jsonb_w_i1d_latitude_degrees', 'btree', 'numeric_ops', 'CREATE INDEX access_log_jsonb_w_i1d_latitude_degrees ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''latitude''->>''degrees'')::numeric))', 'access_log_jsonb_i1d_latitude_degrees'),
        ('X-2', 'jsonb', 'I-1e', 'access_log_jsonb_w_i1e_event_timestamp_utc', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1e_event_timestamp_utc ON log_regex_json_write.access_log_jsonb_w ((doc->''fields''->''event_timestamp''->>''utc''))', 'access_log_jsonb_i1e_event_timestamp_utc'),
        ('X-2', 'jsonb', 'I-2', 'access_log_jsonb_w_i2_gin_jsonb_ops', 'gin', 'jsonb_ops', 'CREATE INDEX access_log_jsonb_w_i2_gin_jsonb_ops ON log_regex_json_write.access_log_jsonb_w USING gin (doc jsonb_ops)', 'access_log_jsonb_i2_gin_jsonb_ops'),
        ('X-3', 'jsonb', 'I-1a', 'access_log_jsonb_w_i1a_record_validity', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1a_record_validity ON log_regex_json_write.access_log_jsonb_w ((doc->''record''->>''record_validity''))', 'access_log_jsonb_i1a_record_validity'),
        ('X-3', 'jsonb', 'I-1b', 'access_log_jsonb_w_i1b_entity_type_code', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1b_entity_type_code ON log_regex_json_write.access_log_jsonb_w ((doc->''fields''->''entity_type''->>''code''))', 'access_log_jsonb_i1b_entity_type_code'),
        ('X-3', 'jsonb', 'I-1c', 'access_log_jsonb_w_i1c_status_code', 'btree', 'int4_ops', 'CREATE INDEX access_log_jsonb_w_i1c_status_code ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''status''->>''code'')::integer))', 'access_log_jsonb_i1c_status_code'),
        ('X-3', 'jsonb', 'I-1d', 'access_log_jsonb_w_i1d_latitude_degrees', 'btree', 'numeric_ops', 'CREATE INDEX access_log_jsonb_w_i1d_latitude_degrees ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''latitude''->>''degrees'')::numeric))', 'access_log_jsonb_i1d_latitude_degrees'),
        ('X-3', 'jsonb', 'I-1e', 'access_log_jsonb_w_i1e_event_timestamp_utc', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1e_event_timestamp_utc ON log_regex_json_write.access_log_jsonb_w ((doc->''fields''->''event_timestamp''->>''utc''))', 'access_log_jsonb_i1e_event_timestamp_utc'),
        ('X-3', 'jsonb', 'I-3', 'access_log_jsonb_w_i3_gin_jsonb_path_ops', 'gin', 'jsonb_path_ops', 'CREATE INDEX access_log_jsonb_w_i3_gin_jsonb_path_ops ON log_regex_json_write.access_log_jsonb_w USING gin (doc jsonb_path_ops)', 'access_log_jsonb_i3_gin_jsonb_path_ops'),
        ('X-4', 'jsonb', 'I-1a', 'access_log_jsonb_w_i1a_record_validity', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1a_record_validity ON log_regex_json_write.access_log_jsonb_w ((doc->''record''->>''record_validity''))', 'access_log_jsonb_i1a_record_validity'),
        ('X-4', 'jsonb', 'I-1b', 'access_log_jsonb_w_i1b_entity_type_code', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1b_entity_type_code ON log_regex_json_write.access_log_jsonb_w ((doc->''fields''->''entity_type''->>''code''))', 'access_log_jsonb_i1b_entity_type_code'),
        ('X-4', 'jsonb', 'I-1c', 'access_log_jsonb_w_i1c_status_code', 'btree', 'int4_ops', 'CREATE INDEX access_log_jsonb_w_i1c_status_code ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''status''->>''code'')::integer))', 'access_log_jsonb_i1c_status_code'),
        ('X-4', 'jsonb', 'I-1d', 'access_log_jsonb_w_i1d_latitude_degrees', 'btree', 'numeric_ops', 'CREATE INDEX access_log_jsonb_w_i1d_latitude_degrees ON log_regex_json_write.access_log_jsonb_w (((doc->''fields''->''latitude''->>''degrees'')::numeric))', 'access_log_jsonb_i1d_latitude_degrees'),
        ('X-4', 'jsonb', 'I-1e', 'access_log_jsonb_w_i1e_event_timestamp_utc', 'btree', 'text_ops', 'CREATE INDEX access_log_jsonb_w_i1e_event_timestamp_utc ON log_regex_json_write.access_log_jsonb_w ((doc->''fields''->''event_timestamp''->>''utc''))', 'access_log_jsonb_i1e_event_timestamp_utc'),
        ('X-4', 'jsonb', 'I-2', 'access_log_jsonb_w_i2_gin_jsonb_ops', 'gin', 'jsonb_ops', 'CREATE INDEX access_log_jsonb_w_i2_gin_jsonb_ops ON log_regex_json_write.access_log_jsonb_w USING gin (doc jsonb_ops)', 'access_log_jsonb_i2_gin_jsonb_ops'),
        ('X-4', 'jsonb', 'I-3', 'access_log_jsonb_w_i3_gin_jsonb_path_ops', 'gin', 'jsonb_path_ops', 'CREATE INDEX access_log_jsonb_w_i3_gin_jsonb_path_ops ON log_regex_json_write.access_log_jsonb_w USING gin (doc jsonb_path_ops)', 'access_log_jsonb_i3_gin_jsonb_path_ops')
    )
        SELECT string_agg(x.doc_type || ' ' || x.index_name || ' ' || x.method || ' ' || x.opclass || ' ' || regexp_replace(regexp_replace(pg_get_indexdef(si.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g'),
                          ' | ' ORDER BY x.doc_type COLLATE "C", x.index_name COLLATE "C")
          INTO v_expected
          FROM design_index x
          LEFT JOIN pg_class si ON si.oid = to_regclass('log_regex_json.' || x.source_index)
         WHERE x.config_id = v_config;

        SELECT string_agg(CASE c.relname WHEN 'access_log_json_w' THEN 'json' ELSE 'jsonb' END || ' ' || ic.relname::text || ' ' || am.amname::text
                          || ' ' || opc.opcname::text || ' ' || regexp_replace(regexp_replace(pg_get_indexdef(ic.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g'),
                          ' | ' ORDER BY CASE c.relname WHEN 'access_log_json_w' THEN 'json' ELSE 'jsonb' END COLLATE "C", ic.relname::text COLLATE "C")
               || CASE WHEN bool_and(i.indisvalid AND i.indisready AND i.indislive AND i.indnatts = 1) THEN '' ELSE ' (NOT VALID)' END
          INTO v_actual
          FROM pg_index i
          JOIN pg_class ic    ON ic.oid = i.indexrelid
          JOIN pg_class c     ON c.oid = i.indrelid
          JOIN pg_am am       ON am.oid = ic.relam
          JOIN pg_opclass opc ON opc.oid = i.indclass[0]
         WHERE c.relnamespace = 'log_regex_json_write'::regnamespace AND NOT i.indisprimary;

        v_count := NULL;
        IF v_config = 'X-1' THEN
            SELECT count(*) INTO v_count
              FROM pg_index ij JOIN pg_class icj ON icj.oid = ij.indexrelid
              JOIN pg_index ib ON ib.indrelid = 'log_regex_json_write.access_log_jsonb_w'::regclass AND NOT ib.indisprimary
              JOIN pg_class icb ON icb.oid = ib.indexrelid
             WHERE ij.indrelid = 'log_regex_json_write.access_log_json_w'::regclass AND NOT ij.indisprimary
               AND replace(icj.relname::text, 'access_log_json_w_', '') = replace(icb.relname::text, 'access_log_jsonb_w_', '')
               AND regexp_replace(regexp_replace(pg_get_indexdef(icj.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g') = regexp_replace(regexp_replace(pg_get_indexdef(icb.oid), 'log_regex_json(_write)?[.]access_log_jsonb?(_w)?', 'TABLE', 'g'), 'access_log_jsonb?(_w)?_', 'IDX_', 'g')
               AND ij.indclass[0] = ib.indclass[0];
        END IF;

        IF v_expected IS NOT NULL AND v_actual IS NOT DISTINCT FROM v_expected AND (v_config <> 'X-1' OR v_count = 5) THEN
            RAISE NOTICE 'I-% PASS  % created = design = live Step 6D definitions (name, method, opclass, normalised definition, valid)%; %',
                replace(v_config, '-', ''), v_config,
                CASE WHEN v_config = 'X-1' THEN ', json and jsonb identical (5 pairs)' ELSE ', jsonb only' END, v_actual;
        ELSE
            v_failed := v_failed + 1;
            RAISE WARNING 'I-% FAIL  %; expected %, actual %, identical json/jsonb pairs %',
                replace(v_config, '-', ''), v_config, v_expected, v_actual, v_count;
        END IF;

        FOR ixd IN
            SELECT ic.relname::text AS index_name
              FROM pg_index i JOIN pg_class ic ON ic.oid = i.indexrelid JOIN pg_class c ON c.oid = i.indrelid
             WHERE c.relnamespace = 'log_regex_json_write'::regnamespace AND NOT i.indisprimary
        LOOP
            EXECUTE format('DROP INDEX log_regex_json_write.%I', ixd.index_name);
        END LOOP;
    END LOOP;

    SELECT count(*) INTO v_count
      FROM pg_index i JOIN pg_class c ON c.oid = i.indrelid
     WHERE c.relnamespace = 'log_regex_json_write'::regnamespace AND NOT i.indisprimary;
    IF v_count = 0 THEN
        RAISE NOTICE 'I-END PASS  secondary indexes left in log_regex_json_write after the configuration checks: 0';
    ELSE
        v_failed := v_failed + 1;
        RAISE WARNING 'I-END FAIL  secondary indexes left in log_regex_json_write after the configuration checks: %', v_count;
    END IF;

    PERFORM set_config('step6e.preflight_failures', v_failed::text, true);
END
$indexes$;

DO $verdict$
BEGIN
    IF current_setting('step6e.preflight_failures')::integer > 0 THEN
        RAISE EXCEPTION 'Step 6E preflight FAILED: % of 41 checks', current_setting('step6e.preflight_failures')
            USING ERRCODE = 'LR017';
    END IF;
    RAISE NOTICE 'Step 6E preflight PASSED: all 41 checks';
END
$verdict$;

ROLLBACK;
